catalog_script_client.script:
function onSubmit() {
    var start = toComparableDate(g_form.getValue('rental_start'))
    var end = toComparableDate(g_form.getValue('rental_end'))

    // Mandatory handling is done by the variables themselves; if either value
    // cannot be parsed, let the server validate it.
    if (start === null || end === null) return true

    if (end < start) {
        g_form.showFieldMsg('rental_end', 'The rental end date cannot be before the rental start date.', 'error', true)
        g_form.addErrorMessage('The rental end date must be on or after the rental start date.')
        return false
    }

    return true

    /**
     * Turns a date variable value into a comparable yyyymmdd number using the
     * user's date format when it is available.
     */
    function toComparableDate(value) {
        if (!value) return null

        var parts = String(value).match(/\d+/g)
        if (!parts || parts.length < 3) return null

        var format = 'yyyy-mm-dd'
        if (typeof g_user_date_format === 'string' && g_user_date_format) {
            format = g_user_date_format.toLowerCase()
        }

        var tokens = format.match(/yyyy|yy|mm|dd/g)
        if (!tokens || tokens.length < 3) tokens = ['yyyy', 'mm', 'dd']

        var year = 0
        var month = 1
        var day = 1

        for (var i = 0; i < 3; i++) {
            var num = parseInt(parts[i], 10)
            if (isNaN(num)) return null
            if (tokens[i].charAt(0) === 'y') year = num < 100 ? 2000 + num : num
            else if (tokens[i] === 'mm') month = num
            else day = num
        }

        if (!year) return null
        return year * 10000 + month * 100 + day
    }
}
